import type { HTTPError } from "../../error.ts";

export const kProblem = "~problem";

export interface ProblemMeta {
  type: string;
  title: string;
  detail?: string;
  instance?: string;
}

export function problemBody(
  error: HTTPError,
  meta: ProblemMeta,
  debug?: boolean,
): Record<string, unknown> {
  const unhandled = error.unhandled;
  return {
    // Extensions first so the standard members below win on key collisions
    ...(unhandled ? undefined : error.body),
    data: unhandled ? undefined : error.data,
    stack: debug && error.stack ? error.stack.split("\n").map((l) => l.trim()) : undefined,
    type: meta.type,
    title: meta.title,
    status: error.status,
    detail: unhandled ? undefined : meta.detail,
    instance: unhandled ? undefined : meta.instance,
  };
}

import { HTTPError, type ErrorInput } from "../error.ts";
import { kProblem, type ProblemMeta } from "./internal/problem.ts";
import { getStatusText } from "./internal/status-text.ts";

export interface ProblemInput<DataT = unknown> extends ErrorInput<DataT> {
  /**
   * URI reference that identifies the problem type (default: `"about:blank"`).
   */
  type?: string;

  /**
   * URI reference that identifies this specific occurrence of the problem.
   */
  instance?: string;
}

