  if (value === kNotFound || value === kHandled || value instanceof Error) {
    return value;
  }
  if (typeof value === "number") {
    return new HTTPError({ status: value });
  }
  const error = new HTTPError({ status: 500, unhandled: true });
  (error as { cause: unknown }).cause = value;
  return error;
}

