function errorResponse(error: HTTPError, debug?: boolean, errHeaders?: Headers): Response {
  const prob = (error as any)[kProblem] as ProblemMarker | undefined;
  let headers: Headers = error.headers
    ? mergeHeaders(prob?.headers || jsonHeaders, error.headers)
    : new Headers(prob?.headers || jsonHeaders);
